styles:
@font-face { font-family: 'Geist'; src: url(../assets/fonts/Geist.woff2) format('woff2'); font-weight: 100 900; font-display: swap; }
@font-face { font-family: 'Geist Mono'; src: url(../assets/fonts/GeistMono.woff2) format('woff2'); font-weight: 100 900; font-display: swap; }
@font-face { font-family: 'Instrument Sans'; src: url(../assets/fonts/InstrumentSans-normal.woff2) format('woff2'); font-weight: 400 700; font-stretch: 75% 100%; font-display: swap; }

:root {
  --bg: #0c0b0a; --fg: #ecebe8; --fg-2: #a3a09a; --fg-3: #8a867f;
  --panel: #141311; --panel-2: #1b1a18; --line: rgba(255,255,255,.08); --border: rgba(255,255,255,.16);
  /* PPQ's brand token from the app's theme (hsl 12 75% 43%) and its hover; one job: what you can act on */
  --brand: #bf3c1b; --brand-hover: #a8341a; --brand-ink: #e97d49; --good: #5fd39a;
  --f-display: 'Instrument Sans', system-ui, sans-serif; --f-body: 'Geist', system-ui, sans-serif; --f-mono: 'Geist Mono', ui-monospace, monospace;
  --display-weight: 400; --display-stretch: 100%; --display-tracking: -0.02em; --display-scale: 1.02;
  --wrap: 1160px; --gutter: clamp(20px, 4vw, 40px);
  --section-space: clamp(72px, 9vw, 128px); --content-space: clamp(40px, 5vw, 64px);
  --column-gap: clamp(32px, 4vw, 56px);
  --ease: cubic-bezier(.2,.7,.2,1);
  --radius: 6px; --radius-card: 12px;
  --surface: #141311; --surface-2: #211c18; --hot: #f3a272; --bad: #df8979; --spring: cubic-bezier(.22,.8,.25,1);
}
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
body { margin: 0; background: var(--bg); color: var(--fg); font: 16px/1.55 var(--f-body); letter-spacing: -0.005em; -webkit-font-smoothing: antialiased; overflow-x: clip; }
img, video { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
h1, h2, h3, p, ul, figure { margin: 0; padding: 0; }
ul { list-style: none; }
button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:focus-visible { outline: 2px solid rgba(255,255,255,.9); outline-offset: 2px; border-radius: var(--radius); }
::selection { background: var(--brand); color: #fff; }
.skip { position: absolute; left: 12px; top: -60px; padding: 8px 12px; border-radius: var(--radius); background: var(--fg); color: var(--bg); z-index: 100; }
.skip:focus { top: 12px; }
.wrap { max-width: calc(var(--wrap) + 2 * var(--gutter)); margin: 0 auto; padding: 0 var(--gutter); }
.display { font-family: var(--f-display); font-weight: var(--display-weight); font-stretch: var(--display-stretch); letter-spacing: var(--display-tracking); line-height: 1.12; text-wrap: balance; }
p { text-wrap: pretty; }
.mono { font-family: var(--f-mono); }
section { scroll-margin-top: 80px; }
/* one faint canvas-grain layer for the whole page */
body::after { content: ''; position: fixed; inset: 0; z-index: 80; pointer-events: none; background: url(../assets/grain.png); background-size: 160px; mix-blend-mode: overlay; opacity: .1; }

/* ---------- buttons: flat, square-ish, one fill ---------- */
.btn { display: inline-flex; align-items: center; justify-content: center; height: 44px; padding: 0 20px; border-radius: var(--radius); border: 1px solid transparent; font: 500 15px/1 var(--f-body); letter-spacing: -0.01em; white-space: nowrap; transition: background-color .15s, border-color .15s, color .15s; }
.btn-primary { background: var(--brand); color: #fff; }
.btn-primary:hover { background: var(--brand-hover); }
.btn-secondary { background: rgba(12,11,10,.35); border-color: rgba(255,255,255,.34); color: var(--fg); }
.btn-secondary:hover { border-color: rgba(255,255,255,.55); background: rgba(255,255,255,.05); }
.btn-light { background: #fff; color: #1a1714; }
.btn-light:hover { background: #efebe6; }
.btn-sm { height: 34px; padding: 0 14px; font-size: 14px; }

/* ---------- nav ---------- */
.nav { position: fixed; inset: 0 0 auto 0; z-index: 50; transition: background-color .3s var(--ease), border-color .3s; border-bottom: 1px solid transparent; }
.nav.scrolled { background: rgba(12,11,10,.82); backdrop-filter: blur(14px) saturate(1.2); border-bottom-color: var(--line); }
.nav .wrap { display: flex; align-items: center; gap: 32px; height: 64px; }
.brand { display: inline-flex; align-items: center; gap: 8px; font-weight: 600; font-size: 16px; letter-spacing: -0.02em; }
.brand img { width: 20px; height: 20px; }
.nav-links { display: flex; gap: 4px; font-size: 14px; font-weight: 500; color: var(--fg-2); }
.nav-links a { padding: 8px 10px; border-radius: var(--radius); transition: color .15s, background-color .15s; }
.nav-links a:hover { color: var(--fg); background: rgba(255,255,255,.05); }
.nav-side { margin-left: auto; display: flex; align-items: center; gap: 8px; font-size: 14px; font-weight: 500; color: var(--fg-2); }
.nav-side > a:not(.btn) { padding: 8px 12px; border-radius: var(--radius); transition: color .15s; }
.nav-side > a:not(.btn):hover { color: var(--fg); }

/* ---------- hero: the copy leads directly into the composer ---------- */
.hero { position: relative; isolation: isolate; padding: clamp(128px, 10vw, 160px) 0 88px; --hero-art-opacity: .66; --hero-art-shade: .38; }
.hero-art { position: absolute; inset: 0; z-index: -2; overflow: hidden; pointer-events: none; opacity: var(--hero-art-opacity); background: #66170e; }
.hero-art::before { content: ''; position: absolute; inset: 0; background: url(../assets/unicorn/magma-poster.webp) center / cover; }
.hero-art.is-ready::before { opacity: 0; }
.hero-art > canvas { display: block; width: 100%; height: 100%; }
.hero-art-shade { position: absolute; inset: 0; z-index: -1; pointer-events: none; background: linear-gradient(180deg, rgba(12,11,10,.44), transparent 28%, transparent 70%, var(--bg)), rgba(12,11,10,var(--hero-art-shade)); }
.hero-art-toggle { position: absolute; right: var(--gutter); bottom: 22px; display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; background: rgba(12,11,10,.5); border: 1px solid rgba(255,255,255,.18); color: var(--fg); }
.hero-art-toggle svg { width: 13px; height: 13px; fill: currentColor; }
.hero-art-toggle .play { display: none; }
.hero-art-toggle[aria-pressed="true"] .pause { display: none; }
.hero-art-toggle[aria-pressed="true"] .play { display: block; }
.hero-art-toggle[hidden] { display: none; }
@media (pointer: coarse) { .hero-art-toggle { width: 44px; height: 44px; } }
.hero + .sec { padding-top: 48px; }
.hero-copy { width: 100%; text-align: center; }
.hero h1 { max-width: 920px; margin-inline: auto; font-size: clamp(32px, 3.2vw, 44px); line-height: 1.12; letter-spacing: -0.035em; }
.hero h1 span { display: block; }
.hero .sub { margin: 22px auto 0; max-width: 660px; font-size: 16px; line-height: 1.6; color: #d7cdc7; }
.hero .demo { margin: 36px auto 0; max-width: 780px; text-align: left; scroll-margin-top: 96px; }
.hero .box textarea { min-height: 88px; }
.hero .modes { justify-content: center; }
.rise { animation: rise .8s var(--ease) both; }
.rise-2 { animation-delay: .06s; }
@keyframes rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }

/* ---------- sections ---------- */
.sec { padding-top: var(--section-space); }
.sec h2 { font-size: calc(clamp(24px, 2.3vw, 32px) * var(--display-scale)); }
.label { margin-bottom: 14px; font-size: 14px; font-weight: 500; color: var(--fg-3); }
.lead { margin-top: 14px; font-size: 17px; line-height: 1.55; color: var(--fg-2); max-width: 32em; }
.reveal { opacity: 0; transform: translateY(16px); transition: opacity .8s var(--ease), transform .8s var(--ease); }
.reveal.in { opacity: 1; transform: none; }

/* ---------- privacy: one scene, scrubbed by scroll — a camera follows one message from your laptop to the AI provider ---------- */
.en-story { display: grid; grid-template-columns: minmax(0, 360px) minmax(0, 1fr); gap: var(--column-gap); }
.en-steps { margin: 0; padding: 0 0 6vh; list-style: none; }
.en-step { min-height: 72vh; display: flex; flex-direction: column; justify-content: center; }
/* the title sits at the top so it peeks above the fold, right under the hero */
.en-step:first-child { min-height: 78vh; justify-content: flex-start; padding-top: 8px; }
.en-step h2 { font-size: calc(clamp(24px, 2.3vw, 32px) * var(--display-scale)); max-width: 9em; } /* = section h2 */
.en-step .lead { margin-top: 16px; max-width: 20em; }
.en-ico { width: 36px; height: 36px; border-radius: 8px; display: grid; place-items: center; border: 1px solid var(--border); color: var(--fg-2); margin-bottom: 20px; transition: color .4s, border-color .4s, background-color .4s; }
.en-ico svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.en-step.on .en-ico { color: var(--fg); }
.en-step[data-s="2"].on .en-ico { color: var(--brand-ink); border-color: rgba(233,125,73,.45); background: rgba(191,60,27,.1); }
.en-step[data-s="4"].on .en-ico { color: var(--good); border-color: rgba(95,211,154,.4); background: rgba(95,211,154,.06); }
.en-step h3 { font-family: var(--f-display); font-weight: var(--display-weight); font-size: calc(20px * var(--display-scale)); letter-spacing: -0.015em; line-height: 1.25; max-width: 15em; text-wrap: balance; }
.en-step p { margin-top: 10px; font-size: 17px; color: var(--fg-2); max-width: 21em; text-wrap: pretty; }
.en-step p.label { margin-top: 0; font-size: 14px; color: var(--fg-3); } /* = the other section labels */

.en-pin-wrap { position: sticky; top: 64px; height: calc(100vh - 64px); display: grid; place-items: center; overflow-x: clip; }
/* every moving part reads its value from a custom property the script sets on each frame */
.en-frame { position: relative; width: 100%; aspect-ratio: 16 / 9; --cx: 50; --cy: 50; --z: 1; --fx: 50; --fy: 50; --sp: 0; --mo: 0; --lit: 0; --gl: 0; --fs: 0; --fi: 0; --vo: 0; --ck: 1; --nm: 1; --sc: 0; --so: 0; }
.en-stage { position: absolute; inset: 0; overflow: hidden; isolation: isolate; background: var(--bg);
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 6%, #000 94%, transparent), linear-gradient(180deg, transparent, #000 6%, #000 92%, transparent);
  -webkit-mask-composite: source-in; mask-image: linear-gradient(90deg, transparent, #000 6%, #000 94%, transparent), linear-gradient(180deg, transparent, #000 6%, #000 92%, transparent); mask-composite: intersect; }
/* camera: keeps the focus point (cx, cy) at the centre of the frame, zoomed by z */
.en-cam { position: absolute; inset: 0; background: var(--bg); transform-origin: 0 0; transform: translate(calc((50 - var(--cx) * var(--z)) * 1%), calc((50 - var(--cy) * var(--z)) * 1%)) scale(var(--z)); will-change: transform; }
/* the render's black lifts to the page colour, so it has no visible edge */
.en-cam img { width: 100%; height: 100%; object-fit: cover; mix-blend-mode: lighten; }
.en-spot { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(24% 34% at calc(var(--fx) * 1%) calc(var(--fy) * 1%), rgba(12,11,10,0) 0%, rgba(12,11,10,0) 40%, rgba(12,11,10, calc(var(--sp) * .82)) 100%); }
/* the enclave lights up while it holds the message, and breathes a little at rest */
.en-glow { position: absolute; left: calc(var(--gx) * 1%); top: calc(var(--gy) * 1%); width: 20%; aspect-ratio: 1; transform: translate(-50%, -50%); pointer-events: none; mix-blend-mode: screen;
  background: radial-gradient(closest-side, rgba(255,140,80,.55), rgba(233,125,73,.22) 50%, rgba(191,60,27,0) 100%); opacity: calc(.04 + var(--gl) * .42); }
.en-glow::after { content: ''; position: absolute; inset: 20%; border-radius: 50%; background: radial-gradient(closest-side, rgba(255,190,140,.5), rgba(255,190,140,0)); animation: en-breathe 3.6s ease-in-out infinite; }
@keyframes en-breathe { 0%, 100% { opacity: .25; transform: scale(.92); } 50% { opacity: .6; transform: scale(1.06); } }
/* attestation: a line of light reads the server from top to bottom */
.en-scan { position: absolute; left: calc(var(--bx1) * 1%); width: calc((var(--bx2) - var(--bx1)) * 1%); top: calc((var(--by1) + (var(--by2) - var(--by1)) * var(--sc)) * 1%); height: 2px; pointer-events: none; opacity: var(--so);
  background: linear-gradient(90deg, rgba(95,211,154,0), rgba(170,255,210,.95) 20%, rgba(170,255,210,.95) 80%, rgba(95,211,154,0)); box-shadow: 0 0 14px 3px rgba(95,211,154,.55); }
.en-path { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.en-path path { fill: none; stroke: #fff4e8; stroke-width: 3.2; stroke-linecap: round; stroke-dasharray: 22 300; stroke-dashoffset: 22; opacity: 0; filter: drop-shadow(0 0 4px rgba(255,236,214,.95)); }

/* labels pinned to points of the picture: they follow the camera without being scaled by it */
.en-pin { position: absolute; z-index: 2; left: calc((50 + (var(--x) - var(--cx)) * var(--z)) * 1%); top: calc((50 + (var(--y) - var(--cy)) * var(--z)) * 1%); }
.en-name { transform: translate(-50%, 0); font-size: 12px; font-weight: 500; color: var(--fg-2); white-space: nowrap; opacity: var(--nm); text-shadow: 0 0 10px var(--bg), 0 0 4px var(--bg); }
.en-name.l { --x: var(--nlx, 16.5); --y: var(--ny, 83); } .en-name.e { --x: var(--nex, 49); --y: var(--ny, 83); } .en-name.p { --x: var(--npx, 82); --y: var(--ny, 83); }

.en-msg { --x: var(--mx, 19); --y: var(--my, 42); width: 264px; transform: translate(-50%, calc(-100% - 10px)); padding: 11px 13px 12px; border-radius: 10px; background: rgba(22,21,19,.88); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); opacity: var(--mo);
  border: 1px solid rgba(calc(255 - 22 * var(--lit)), calc(255 - 130 * var(--lit)), calc(255 - 182 * var(--lit)), calc(.12 + .48 * var(--lit)));
  box-shadow: 0 18px 36px -18px rgba(0,0,0,.95), 0 0 46px -6px rgba(191,60,27, calc(.5 * var(--lit))); }
.en-msg .k { display: block; font-size: 12px; font-weight: 500; color: color-mix(in srgb, var(--brand-ink) calc(var(--lit) * 100%), var(--fg-3)); }
.en-msg .t { margin-top: 4px; font-size: 14px; line-height: 1.42; color: var(--fg); height: 2.84em; overflow: hidden; word-break: break-word; }
.en-msg .t.c { font: 12px/1.6 var(--f-mono); height: 3.2em; color: var(--fg-3); word-break: break-all; }
.en-msg .t i { font-style: normal; color: var(--fg-3); }
/* the card's footer: what we also see on the way in, and that your IP stays behind on the way out */
.en-feet { display: grid; max-height: calc(max(var(--fs), var(--fi)) * 44px); overflow: hidden; }
.en-foot { grid-area: 1 / 1; margin-top: 9px; padding-top: 9px; border-top: 1px solid rgba(255,255,255,.08); display: flex; align-items: center; flex-wrap: wrap; gap: 5px; font-size: 12px; color: var(--fg-3); }
.en-foot.seen { opacity: var(--fs); } .en-foot.ip { opacity: var(--fi); }
.en-chip { font: 12px var(--f-mono); padding: 2px 6px; border-radius: 4px; background: rgba(255,255,255,.06); color: var(--fg-2); }
.en-foot.ip .en-chip { text-decoration: line-through; text-decoration-color: rgba(255,255,255,.55); }

.en-verify { --x: var(--vx, 50); --y: var(--vy, 8); transform: translate(-50%, calc((1 - var(--vo)) * 10px)); width: max-content; padding: 13px 18px 14px; border-radius: 12px; background: rgba(22,21,19,.9); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border: 1px solid rgba(95,211,154,.3); box-shadow: 0 20px 40px -20px rgba(0,0,0,.95); opacity: var(--vo); }
.en-verify b { display: flex; align-items: center; gap: 8px; font-size: 14px; font-weight: 500; color: var(--good); }
.en-verify b svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.en-verify .tick { stroke-dasharray: 1; stroke-dashoffset: var(--ck); }
.en-verify ul { margin-top: 7px; padding-left: 25px; display: grid; gap: 3px; font-size: 13px; color: var(--fg-2); }

.en-tech { margin-top: 8px; border-top: 1px solid var(--line); padding-top: 18px; max-width: 760px; }
.en-tech summary { display: inline-flex; align-items: center; gap: 8px; cursor: pointer; list-style: none; font-size: 15px; font-weight: 500; color: var(--fg-2); transition: color .15s; }
.en-tech summary::-webkit-details-marker { display: none; }
.en-tech summary::before { content: ''; width: 6px; height: 6px; border-right: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor; transform: rotate(-45deg); transition: transform .2s var(--ease); margin-right: 4px; }
.en-tech[open] summary::before { transform: rotate(45deg); }
.en-tech summary:hover { color: var(--fg); }
.en-tech summary small { font-size: 13px; font-weight: 400; color: var(--fg-3); }
.en-tech dl { margin: 22px 0 0; display: grid; grid-template-columns: 130px minmax(0, 1fr); gap: 14px 24px; font-size: 15px; }
.en-tech dt { color: var(--fg); font-weight: 500; }
.en-tech dd { margin: 0; color: var(--fg-2); }
.en-tech .proof { margin-top: 18px; }
.en-tech .cmd code { white-space: normal; overflow-wrap: normal; }
/* 3D version: a WebGL canvas fills the pinned column; the cards and names are placed by the script */
.en-3d { aspect-ratio: auto; height: min(calc(100vh - 112px), 820px); background: var(--bg); isolation: isolate; }
/* the renderer's black lifts to the page colour, so the canvas has no visible edge */
.en-3d .en-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; mix-blend-mode: lighten;
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 5%, #000 95%, transparent), linear-gradient(180deg, transparent, #000 6%, #000 94%, transparent);
  -webkit-mask-composite: source-in; mask-image: linear-gradient(90deg, transparent, #000 5%, #000 95%, transparent), linear-gradient(180deg, transparent, #000 6%, #000 94%, transparent); mask-composite: intersect; }
.en-3d .en-fallback { display: none; position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; mix-blend-mode: lighten; }
.en-3d.no-3d .en-fallback { display: block; }
.en-3d.no-3d .en-canvas, .en-3d.no-3d .en-msg, .en-3d.no-3d .en-name { display: none; }
.en-3d.no-3d .en-verify { opacity: 1; left: 50%; top: 4%; transform: translate(-50%, 0); }
.en-3d .en-msg, .en-3d .en-verify, .en-3d .en-name { position: absolute; z-index: 2; left: 0; top: 0; }
.en-3d .en-msg { width: 264px; }
.en-3d .en-name { transform: translate(-50%, 0); opacity: 0; }
.cmd { display: flex; align-items: center; gap: 12px; padding: 10px 10px 10px 16px; border-radius: 8px; background: var(--panel); border: 1px solid var(--line); font: 13px/1.4 var(--f-mono); }
.cmd code { white-space: nowrap; overflow-x: auto; flex: 1; min-width: 0; scrollbar-width: none; }
.cmd .s { color: var(--fg-3); }
.copy { margin-left: auto; flex: none; height: 28px; padding: 0 10px; border-radius: 4px; border: 1px solid var(--line); font: 500 12px var(--f-body); color: var(--fg-2); transition: color .15s, border-color .15s; }
.copy:hover { color: var(--fg); border-color: var(--border); }
.proof { margin-top: 12px; display: flex; flex-wrap: wrap; gap: 6px 16px; font-size: 13px; color: var(--fg-3); }
.proof a { color: var(--fg-2); text-decoration: underline; text-decoration-color: rgba(255,255,255,.25); text-underline-offset: 3px; }
.proof a:hover { color: var(--fg); text-decoration-color: var(--fg-2); }

/* api */
.api { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); gap: 72px; align-items: center; }
.code { position: relative; border-radius: var(--radius-card); background: var(--panel); border: 1px solid var(--line); padding: 18px 0 22px; font: 14px/1.8 var(--f-mono); overflow: hidden; }
.code .top { display: flex; align-items: center; gap: 6px; padding: 0 20px 14px; margin-bottom: 12px; border-bottom: 1px solid var(--line); font: 12.5px var(--f-body); color: var(--fg-3); }
.code .top i { width: 8px; height: 8px; border-radius: 50%; background: #2c2a27; }
.code .top span { margin-left: 8px; }
.code .ln { display: block; padding: 0 24px; white-space: pre; overflow-x: auto; transition: background-color .4s; }
.code .k { color: #c9b08a; }
.code .s { color: var(--fg); }
.code .ln.changed { background: rgba(191,60,27,.16); box-shadow: inset 2px 0 0 var(--brand); }
.code .ln.changed .s { color: var(--brand-ink); }
.code .tag { position: absolute; right: 16px; top: 13px; font: 500 12px var(--f-body); padding: 4px 8px; border-radius: 4px; background: var(--brand); color: #fff; opacity: 0; transition: opacity .4s; }
.code.done .tag { opacity: 1; }
.tools { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 28px; }
.tools a { display: inline-flex; align-items: center; gap: 8px; height: 36px; padding: 0 12px 0 10px; border-radius: var(--radius); background: var(--panel); border: 1px solid var(--line); font-size: 14px; color: var(--fg-2); transition: color .15s, border-color .15s; }
.tools a:hover { color: var(--fg); border-color: var(--border); }
.tools img { width: 18px; height: 18px; object-fit: contain; border-radius: 4px; }

/* pricing */
.price-grid { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); gap: var(--column-gap); align-items: center; margin-top: var(--content-space); }
.block { position: relative; border-radius: var(--radius-card); overflow: hidden; background: var(--brand); color: #fff; padding: 40px 40px 36px; }
.block::after { content: ''; position: absolute; inset: 0; pointer-events: none; background: url(../assets/grain.png); background-size: 160px; mix-blend-mode: overlay; opacity: .18; }
.block > * { position: relative; z-index: 1; }
.block .big { font-family: var(--f-display); font-weight: var(--display-weight); font-stretch: var(--display-stretch); letter-spacing: -0.03em; font-size: calc(clamp(36px, 3vw, 44px) * var(--display-scale)); line-height: 1; }
.block .big-sub { margin-top: 10px; font-size: 18px; font-weight: 500; }
.block .buys { margin-top: 22px; display: inline-block; padding: 8px 12px; border-radius: 8px; background: rgba(0,0,0,.16); font-size: 15px; color: rgba(255,255,255,.94); }
.block .buys b { margin: 0 3px; font: 500 20px var(--f-mono); color: #fff; font-variant-numeric: tabular-nums; }
.block .pay { margin-top: 26px; display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.block .pay i { width: 34px; height: 34px; border-radius: 50%; background: #1c0c06; display: grid; place-items: center; }
.block .pay img { width: 20px; height: 20px; }
.block .pay span { margin-left: 4px; font-size: 14px; color: rgba(255,255,255,.94); }
.block .btn { margin-top: 30px; }
.prices { align-self: center; }
.prices li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px 16px; align-items: baseline; padding: 16px 0; }
.prices .m { font-size: 16px; }
.prices b { font: 400 16px var(--f-mono); }
.prices .bar { grid-column: 1 / -1; height: 3px; border-radius: 2px; background: rgba(255,255,255,.07); overflow: hidden; }
.prices .bar i { display: block; height: 100%; width: 0; border-radius: 2px; background: var(--brand); transition: width 1.2s var(--ease); }
.prices.in .bar i { width: var(--w); }
.prices-cap { margin-top: 12px; font-size: 13px; color: var(--fg-3); }

/* close: the valley painting, as before */
.close { position: relative; margin-top: var(--section-space); min-height: clamp(560px, 50vw, 720px); padding: var(--content-space) 0 0; text-align: center; overflow: clip; isolation: isolate; }
.close-art { position: absolute; inset: 0; z-index: -2; }
.close-art picture { display: contents; }
.close-art img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 100%; }
.close::before { content: ''; position: absolute; inset: 0; z-index: -1; pointer-events: none; background: linear-gradient(180deg, var(--bg) 0%, rgba(12,11,10,.5) 15%, rgba(12,11,10,.12) 40%, rgba(12,11,10,0) 60%), linear-gradient(0deg, var(--bg) 0%, rgba(12,11,10,0) 16%); }
.close h2 { font-size: calc(clamp(30px, 3vw, 44px) * var(--display-scale)); text-shadow: 0 2px 30px rgba(12,11,10,.6); }
.close .wrap p { margin-top: 14px; font-size: 17px; color: var(--fg); opacity: .84; text-shadow: 0 1px 20px rgba(12,11,10,.9); }
.close .ctas { display: flex; gap: 12px; justify-content: center; margin-top: 30px; flex-wrap: wrap; }
.plaque { position: absolute; left: var(--gutter); bottom: 40px; display: grid; gap: 2px; padding: 10px 14px 11px; border-radius: 8px; background: rgba(14,12,10,.8); backdrop-filter: blur(10px); border: 1px solid var(--line); font-size: 13px; line-height: 1.4; text-align: left; }
.plaque b { font-weight: 500; }
.plaque span { color: var(--fg-2); }

/* footer */
.foot { padding: var(--content-space) 0 48px; font-size: 14px; color: var(--fg-2); }
.foot-grid { display: grid; grid-template-columns: 1.4fr repeat(4, 1fr); gap: 32px; }
.foot h3 { font-size: 13px; font-weight: 500; color: var(--fg-3); margin-bottom: 12px; }
.foot li + li { margin-top: 8px; }
.foot a:hover { color: var(--fg); }
.foot-base { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px 24px; margin-top: var(--content-space); font-size: 13px; color: var(--fg-3); }

.m-only { display: none; }
@media (max-width: 960px) {
  .nav-links, .nav-side > a:not(.btn) { display: none; }
  .api, .price-grid { grid-template-columns: minmax(0, 1fr); gap: 40px; }
  .api > *, .price-grid > * { min-width: 0; }
  .frame { max-width: 620px; }
  .foot-grid { grid-template-columns: 1fr 1fr; }
  .foot-grid > :first-child { grid-column: 1 / -1; }
}
@media (max-width: 860px) { .d-only { display: none; } .m-only { display: block; } .frame { aspect-ratio: 9 / 10; } .frame .window { aspect-ratio: 8 / 9; top: 7%; left: 6%; width: 94%; } }
/* phones: keep the copy and composer together in the first screen */
@media (max-width: 760px) {
  .hero { padding: 112px 0 56px; }
  .hero h1 { max-width: 18em; font-size: clamp(26px, 6.7vw, 34px); line-height: 1.15; letter-spacing: -0.03em; }
  .hero h1 span { display: inline; }
  .hero .sub { margin-top: 20px; max-width: 34em; font-size: 15px; line-height: 1.6; }
  .hero .demo { margin-top: 30px; }
  .hero .box textarea { min-height: 72px; }
  .hero .modes { gap: 0; margin-inline: 0; padding-inline: 0; flex-wrap: wrap; }
  .hero .modes button { padding-inline: 7px; gap: 5px; font-size: 13px; }
  .hero .modes svg.i { width: 14px; height: 14px; }
  .hero .trig { flex: 0 1 auto; }
  .hero .trig .nm { max-width: 132px; }
  .hero .box .bot > .ib { width: 32px; }
  .sec h2, .app h2 { font-size: 24px; }
  .close h2, .block .big { font-size: 28px; }
  .close { min-height: clamp(560px, 80svh, 680px); }
  .close::before { background: linear-gradient(180deg, var(--bg) 0%, rgba(12,11,10,.55) 12%, rgba(12,11,10,.2) 34%, rgba(12,11,10,0) 48%), linear-gradient(0deg, var(--bg) 0%, rgba(12,11,10,0) 12%); }
  .close .plaque { display: none; }
}
@media (max-width: 520px) {
  .block { padding: 30px 24px; }
  .code { font-size: 12.5px; }
  .code .ln { padding: 0 16px; }
  .cmd code { white-space: normal; overflow-wrap: anywhere; }
}
@media (max-width: 380px) {
  .hero .modes svg.i { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
  .reveal { opacity: 1; transform: none; }
}

/* ---------- chat: the app's own composer on the page (study: ../chat/r2/) ---------- */
:root { --app-surface: #1d1d1d; --app-muted: #292929; --app-border: #2e2e2e; --app-border-strong: #3b3b3b; --app-fg: #ededed; --app-fg-2: #bbbbbb; --app-fg-3: #8f8f8f; }
.cmp textarea, .cmp input { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; }
.app .btn { gap: 10px; }
svg.i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.btn svg.mark { width: 18px; height: 18px; fill: currentColor; margin-top: -2px; }
.btn svg.mark.sm { width: 15px; height: 15px; margin-top: 0; }
.a-head { text-align: center; display: grid; justify-items: center; }
.a-head h2 { max-width: 15em; }
.a-head .lead { max-width: 30em; }
.demo { margin: 48px auto 0; max-width: 780px; }
.cproof { margin-top: 14px; font-size: 13px; color: var(--fg-3); text-align: center; text-wrap: balance; }
.cproof svg.i { display: inline-block; width: 14px; height: 14px; color: var(--good); vertical-align: -2px; margin-right: 6px; }
.cproof a { margin-left: 4px; white-space: nowrap; color: var(--fg-2); text-decoration: underline; text-decoration-color: rgba(255,255,255,.25); text-underline-offset: 3px; }
.cproof a:hover { color: var(--fg); }
/* ======================================================= the composer (replica of PPQdotAI ChatInput) */
.cmp { position: relative; }
.modes { display: flex; justify-content: center; gap: 4px; margin-bottom: 14px; flex-wrap: wrap; }
.b-demo .modes { justify-content: flex-start; }
.modes button { display: inline-flex; align-items: center; gap: 8px; height: 38px; padding: 0 14px; border-radius: 999px; font-size: 15px; color: var(--app-fg-2); transition: background-color .15s, color .15s; }
.modes button:hover { color: var(--app-fg); }
.modes button[aria-pressed="true"] { background: var(--app-muted); color: var(--app-fg); }
.box { position: relative; border-radius: 24px; background: var(--app-surface); border: 1px solid var(--app-border); box-shadow: 0 30px 70px -40px rgba(0,0,0,.9); transition: border-color .2s, box-shadow .2s; }
.box:focus-within { border-color: var(--app-border-strong); }
.box .top { position: relative; display: flex; align-items: flex-start; gap: 0; padding: 14px 16px 2px; }
.box .shield { flex: none; margin-top: 3px; color: var(--app-fg-2); }
.box textarea { flex: 1; min-width: 0; resize: none; outline: none; padding: 2px 10px; min-height: 52px; max-height: 200px; font-size: 16px; line-height: 1.55; color: var(--app-fg); }
.box textarea::placeholder { color: var(--app-fg-3); }
.ghost { position: absolute; left: 50px; top: 16px; right: 20px; font-size: 16px; line-height: 1.55; color: var(--app-fg-3); pointer-events: none; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ghost .car { display: inline-block; width: 1.5px; height: 1.05em; margin-left: 1px; background: var(--app-fg-3); vertical-align: -0.15em; animation: blink 1s steps(1) infinite; }
@keyframes blink { 50% { opacity: 0; } }
.box .bot { display: flex; align-items: center; gap: 4px; padding: 6px 10px 10px; }
.ib { position: relative; width: 38px; height: 38px; border-radius: 999px; display: grid; place-items: center; color: var(--app-fg-2); transition: background-color .15s, color .15s; flex: none; }
.ib:hover { background: var(--app-muted); color: var(--app-fg); }
.trig { display: inline-flex; align-items: center; gap: 8px; height: 38px; padding: 0 10px 0 8px; border-radius: 999px; font-size: 15px; font-weight: 500; color: var(--app-fg); min-width: 0; transition: background-color .15s; }
.trig:hover, .trig[aria-expanded="true"] { background: var(--app-muted); }
.trig .nm { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 220px; }
.trig .chev { width: 15px; height: 15px; color: var(--app-fg-3); transition: transform .2s; }
.trig[aria-expanded="true"] .chev { transform: rotate(180deg); }
.trig .bub { color: var(--app-fg-2); }
.lg { width: 20px; height: 20px; flex: none; border-radius: 5px; object-fit: contain; }
.lg.inv { filter: invert(1); }
.lg.ini { display: grid; place-items: center; border-radius: 50%; background: #3a3936; color: #e8e6e1; font: 600 10.5px/1 var(--f-body); }
.rsn { display: inline-flex; align-items: center; gap: 6px; height: 38px; padding: 0 10px; border-radius: 999px; font-size: 14px; color: var(--app-fg-2); transition: background-color .15s; }
.rsn:hover { background: var(--app-muted); color: var(--app-fg); }
.rsn .chev { width: 14px; height: 14px; }
.rsn[hidden] { display: none; }
.sp { flex: 1; }
.send { width: 40px; height: 40px; border-radius: 50%; display: grid; place-items: center; background: #f2f2f2; color: #151515; flex: none; transition: transform .15s, background-color .15s; }
.send:hover { background: #fff; }
.send:active { transform: scale(.94); }
.send .up { display: none; }
.cmp.has-text .send .up { display: block; }
.cmp.has-text .send .wave { display: none; }
.tip { position: absolute; bottom: calc(100% + 8px); left: 50%; translate: -50% 0; padding: 6px 9px; border-radius: 6px; background: #f2f2f2; color: #151515; font-size: 12px; font-weight: 500; white-space: nowrap; pointer-events: none; opacity: 0; transition: opacity .15s; z-index: 5; }
.ib:hover .tip, .ib:focus-visible .tip { opacity: 1; }

/* model picker popover */
.pick { position: absolute; left: 0; right: 0; bottom: calc(100% + 10px); z-index: 20; max-width: 640px; border-radius: 16px; background: #1f1f1f; border: 1px solid var(--app-border-strong); box-shadow: 0 30px 80px -20px rgba(0,0,0,.9); display: flex; flex-direction: column; max-height: min(520px, 70vh); overflow: hidden; opacity: 0; transform: translateY(6px); pointer-events: none; transition: opacity .18s var(--ease), transform .22s var(--ease); }
.cmp.open .pick { opacity: 1; transform: none; pointer-events: auto; }
.cmp.down .pick { bottom: auto; top: calc(100% + 10px); transform: translateY(-6px); }
.cmp.down.open .pick { transform: none; }
.pick .srch { display: flex; align-items: center; gap: 10px; padding: 14px 16px; border-bottom: 1px solid var(--app-border); color: var(--app-fg-3); }
.pick .srch input { flex: 1; min-width: 0; outline: none; font-size: 15px; color: var(--app-fg); }
.pick .srch input::placeholder { color: var(--app-fg-3); }
.pick .tabs { display: flex; gap: 2px; padding: 8px 10px 0; border-bottom: 1px solid var(--app-border); overflow-x: auto; scrollbar-width: none; }
.pick .tabs button { display: inline-flex; align-items: center; gap: 7px; padding: 8px 12px 10px; font-size: 14px; color: var(--app-fg-3); border-bottom: 2px solid transparent; white-space: nowrap; }
.pick .tabs button svg.i { width: 16px; height: 16px; }
.pick .tabs button[aria-selected="true"] { color: var(--app-fg); border-bottom-color: var(--app-fg); }
.pick .tiers { display: flex; gap: 6px; padding: 10px 14px 4px; flex-wrap: wrap; }
.pick .tiers button { height: 28px; padding: 0 10px; border-radius: 999px; border: 1px solid var(--app-border-strong); font-size: 12.5px; color: var(--app-fg-2); display: inline-flex; gap: 6px; align-items: center; }
.pick .tiers button span { color: var(--app-fg-3); }
.pick .tiers button[aria-pressed="true"] { background: var(--app-fg); border-color: var(--app-fg); color: #151515; }
.pick .tiers button[aria-pressed="true"] span { color: #555; }
.pick > :not(.list) { flex: none; }
.pick .list { flex: 1 1 auto; min-height: 0; overflow-y: auto; padding: 4px 6px 8px; overscroll-behavior: contain; }
.pick .gh { padding: 12px 10px 6px; font-size: 12.5px; font-weight: 500; color: var(--app-fg-3); }
.mrow { width: 100%; display: flex; align-items: center; gap: 12px; padding: 9px 10px; border-radius: 10px; text-align: left; }
.mrow:hover, .mrow.kb { background: var(--app-muted); }
.mrow .tx { flex: 1; min-width: 0; }
.mrow .n { display: flex; align-items: center; gap: 8px; font-size: 14.5px; color: var(--app-fg); }
.mrow .n b { font-weight: 400; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mrow .d { font-size: 12.5px; color: var(--app-fg-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mrow .pr { font: 12.5px var(--f-mono); color: var(--app-fg-3); letter-spacing: .02em; }
.mrow .pr i { font-style: normal; color: #4a4a4a; }
.mrow .ck { width: 16px; color: var(--app-fg); visibility: hidden; }
.mrow.sel .ck { visibility: visible; }
.tier { position: relative; flex: none; height: 19px; padding: 0 6px; border-radius: 5px; font: 600 10.5px/19px var(--f-body); letter-spacing: .04em; background: rgba(255,255,255,.08); color: var(--app-fg-2); cursor: help; }
.tier.Z { background: rgba(140,170,255,.12); color: #b4c6ff; }
.tier.E { background: rgba(95,211,154,.14); color: var(--good); }
.pick .pfoot { display: flex; align-items: center; gap: 10px; padding: 10px 16px; border-top: 1px solid var(--app-border); font-size: 12.5px; color: var(--app-fg-3); }
.pick .pfoot svg.i { width: 14px; height: 14px; color: var(--good); }
.pick .empty { padding: 28px 12px; text-align: center; font-size: 14px; color: var(--app-fg-3); }
.ttip { position: fixed; z-index: 90; max-width: 260px; padding: 9px 11px; border-radius: 8px; background: #f2f2f2; color: #151515; font-size: 12.5px; line-height: 1.45; pointer-events: none; opacity: 0; transition: opacity .12s; box-shadow: 0 10px 30px -10px rgba(0,0,0,.6); }
.ttip.on { opacity: 1; }
.ttip b { font-weight: 600; }

/* hand-off after send */
.handoff { margin-top: 14px; display: none; align-items: center; justify-content: center; gap: 10px; font-size: 13px; color: var(--fg-2); }
.cmp.sent .handoff { display: flex; }
.cmp.sent ~ .cproof { display: none; }
.handoff .spin { width: 14px; height: 14px; border-radius: 50%; border: 2px solid rgba(255,255,255,.2); border-top-color: var(--fg); animation: spin .8s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.handoff { flex-wrap: wrap; text-align: center; }
.handoff a { color: var(--fg); text-decoration: underline; text-underline-offset: 3px; }

/* ======================================================= mobile app block */
.app { margin-top: 0; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--column-gap); align-items: center; border-radius: 20px; background: var(--panel); border: 1px solid var(--line); padding: 0 clamp(24px, 4vw, 48px); overflow: hidden; min-height: 460px; }
.app h2 { font-size: calc(clamp(24px, 2.3vw, 32px) * var(--display-scale)); }
.app .lead { font-size: 17px; max-width: 26em; }
.app .actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 32px; }
.app .vis { align-self: stretch; display: flex; justify-content: center; align-items: flex-start; padding-top: 56px; height: 460px; }
.phone { position: relative; width: 250px; padding: 7px; border-radius: 36px; background: #1e1d1b; box-shadow: inset 0 0 0 1px rgba(255,255,255,.14), 0 40px 70px -30px rgba(0,0,0,.95); flex: none; }
.phone img { width: 100%; aspect-ratio: 1200 / 2460; object-fit: cover; border-radius: 29px; }
@media (max-width: 860px) {
  .demo { margin-top: 40px; }
  .modes { justify-content: flex-start; overflow-x: auto; flex-wrap: nowrap; scrollbar-width: none; margin-inline: calc(-1 * var(--gutter)); padding-inline: var(--gutter); }
  .modes button { font-size: 14px; padding: 0 12px; }
  .box .bot { gap: 0; padding: 4px 6px 8px; }
  /* the app's own phone layout: no provider logo, no reasoning control */
  .trig .nm { max-width: 160px; }
  .trig .lgw, .rsn { display: none !important; }
  .pick { max-height: 64vh; }
  .cproof { text-align: left; }
  .app { grid-template-columns: minmax(0, 1fr); padding: 32px 24px 0; gap: 32px; }
  .app .vis { height: 300px; padding-top: 0; }
  .phone { width: 220px; }
}

/* ================= API section (from api/v8.html, classes prefixed ax-) ================= */
.ax-textlink { color: var(--fg-2); text-decoration: underline; text-decoration-color: rgba(255,255,255,.25); text-underline-offset: 4px; transition: color .15s; }
.ax-textlink:hover { color: var(--fg); }
/* ================= 1 · one key, every tool ================= */
.ax-intro h2 { max-width: 20em; }
.ax-sky { position: relative; height: 440px; max-width: 980px; margin: 28px auto 0; --glow: 0; }
.ax-sky svg.ax-lines { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.ax-sky .ax-base { fill: none; stroke: rgba(255,255,255,.06); stroke-width: 1; }
.ax-sky .ax-lit-path { fill: none; stroke-width: 1; opacity: 0; transition: opacity .7s var(--ease), stroke-width .3s; }
.ax-sky .ax-lit-path.ax-on { opacity: 1; }
.ax-sky .ax-lit-path.ax-hot { stroke-width: 1.6; }
.ax-sky .ax-packet { fill: none; stroke: #f3b48c; stroke-width: 1.6; stroke-linecap: round; opacity: 0; transition: opacity .4s; }
.ax-sky .ax-packet.ax-on { opacity: 1; }
.ax-hub { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); z-index: 2; width: 88px; height: 88px; border-radius: 24px; display: grid; place-items: center;
  background: linear-gradient(180deg, #1c1a18 0%, #131210 100%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.07), 0 0 0 1px rgba(233,125,73,calc(.18 + var(--glow) * .22)), 0 0 calc(var(--glow) * 36px) rgba(191,60,27,calc(var(--glow) * .28)), 0 18px 40px -20px rgba(0,0,0,.9);
  transition: box-shadow .6s var(--ease); }
/* the flame stays put; only its tongues move (a slow noise warp on the upper part) */
.ax-flame { position: relative; width: 48px; height: 48px; }
.ax-flame img { position: absolute; inset: 0; width: 100%; height: 100%; user-select: none; -webkit-user-drag: none; }
.ax-flame .ax-still { -webkit-mask-image: linear-gradient(0deg, #000 38%, transparent 62%); mask-image: linear-gradient(0deg, #000 38%, transparent 62%); }
.ax-flame .ax-tongues { filter: url(#ax-flame-warp); -webkit-mask-image: linear-gradient(0deg, transparent 30%, #000 58%); mask-image: linear-gradient(0deg, transparent 30%, #000 58%); }
.ax-flame .ax-inner { mix-blend-mode: screen; filter: url(#ax-flame-warp-soft); animation: ax-core 3.6s ease-in-out infinite alternate; }
@keyframes ax-core { from { opacity: .35; } to { opacity: .8; } }
.ax-ember { position: absolute; left: 50%; top: 14%; width: 2.5px; height: 2.5px; border-radius: 50%; background: #f6b98f; opacity: 0; pointer-events: none; animation: ax-rise 5s ease-out infinite; }
.ax-ember + .ax-ember { animation-delay: 2.6s; --dx: -6px; width: 2px; height: 2px; }
@keyframes ax-rise { 0% { opacity: 0; transform: translate(-50%, 0); } 20% { opacity: .7; } 100% { opacity: 0; transform: translate(calc(-50% + var(--dx, 4px)), -30px); } }

.ax-node { position: absolute; transform: translate(-50%, -50%); z-index: 3; }
.ax-node .ax-tile { position: relative; width: 54px; height: 54px; border-radius: 15px; display: grid; place-items: center; background: linear-gradient(180deg, #1e1c1a 0%, #121110 100%); box-shadow: inset 0 1px 0 rgba(255,255,255,.07), 0 0 0 1px rgba(255,255,255,.07), 0 14px 30px -18px rgba(0,0,0,.9); transition: transform .35s var(--spring), box-shadow .6s var(--ease); }
.ax-node img { width: 26px; height: 26px; object-fit: contain; border-radius: 6px; opacity: .28; filter: grayscale(1); transition: opacity .6s var(--ease), filter .6s var(--ease); }
.ax-node img.ax-inv { filter: grayscale(1) invert(1); }
.ax-node > span:last-child { position: absolute; left: 50%; top: calc(100% + 8px); transform: translateX(-50%); font-size: 13px; color: var(--fg-3); opacity: .45; transition: opacity .6s, color .6s; white-space: nowrap; }
.ax-node.ax-top > span:last-child { top: auto; bottom: calc(100% + 8px); }
.ax-node.ax-lit .ax-tile { box-shadow: inset 0 1px 0 rgba(255,255,255,.08), 0 0 0 1px rgba(233,125,73,.3), 0 14px 30px -18px rgba(0,0,0,.9); animation: ax-pop .5s var(--spring); }
.ax-node.ax-lit img { opacity: 1; filter: none; }
.ax-node.ax-lit img.ax-inv { filter: invert(1); }
.ax-node.ax-lit > span:last-child { opacity: 1; color: var(--fg-2); }
.ax-node:hover .ax-tile { transform: translateY(-4px) scale(1.06); }
.ax-node:hover > span:last-child { color: var(--fg); }
@keyframes ax-pop { 0% { transform: scale(1); } 40% { transform: scale(1.12); } 100% { transform: scale(1); } }
.ax-sky-foot { margin-top: 24px; text-align: center; font-size: 14px; color: var(--fg-3); }

/* ================= 2 · what people build ================= */
.ax-story { position: relative; margin-top: var(--content-space); display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); gap: var(--column-gap); }
.ax-steps .label { margin: 0 0 24px; font-size: 14px; color: var(--fg-3); }
.ax-step { min-height: 84vh; display: flex; flex-direction: column; justify-content: center; padding: 40px 0; opacity: .25; transition: opacity .5s var(--ease); }
.ax-step:first-of-type { min-height: 74vh; }
.ax-step.ax-on { opacity: 1; }
.ax-step .ax-n { font: 13px var(--f-mono); color: var(--fg-3); transition: color .5s; }
.ax-step.ax-on .ax-n { color: var(--brand-ink); }
.ax-step h3 { margin-top: 12px; font-size: 20px; }
.ax-step p { margin-top: 14px; font-size: 17px; color: var(--fg-2); max-width: 25em; }
.ax-tools { margin-top: 26px; display: flex; flex-wrap: wrap; gap: 10px 20px; font-size: 14px; color: var(--fg-2); }
.ax-tools > * { display: inline-flex; align-items: center; gap: 8px; transition: color .15s; }
.ax-tools img { width: 18px; height: 18px; object-fit: contain; border-radius: 4px; }
.ax-tools img.ax-inv { filter: invert(1); }
.ax-tools a:hover { color: var(--fg); }

.ax-stage-col { position: relative; }
.ax-stage { position: sticky; top: max(80px, calc(50vh - 240px)); height: 480px; }
.ax-scene { position: absolute; inset: 0; display: grid; place-items: center; opacity: 0; transform: translateY(22px) scale(.97); transition: opacity .55s var(--ease), transform .75s var(--spring); pointer-events: none; }
.ax-scene.ax-on { opacity: 1; transform: none; pointer-events: auto; }
.ax-replay { position: absolute; z-index: 6; height: 28px; padding: 0 11px; border-radius: 999px; font-size: 12px; color: var(--fg-2); background: rgba(30,28,26,.85); box-shadow: inset 0 0 0 1px rgba(255,255,255,.1); backdrop-filter: blur(8px); opacity: 0; transform: translateY(6px); transition: opacity .3s, transform .3s, color .15s; pointer-events: none; }
.ax-scene.ax-done .ax-replay { opacity: 1; transform: none; pointer-events: auto; }
.ax-replay:hover { color: var(--fg); }
.ax-spin { display: inline-block; width: 11px; height: 11px; border-radius: 50%; border: 1.5px solid rgba(255,255,255,.18); border-top-color: var(--hot); animation: ax-rot .7s linear infinite; vertical-align: -1px; }
@keyframes ax-rot { to { transform: rotate(360deg); } }
.ax-enter { animation: ax-enter .45s var(--spring) both; }
@keyframes ax-enter { from { opacity: 0; transform: translateY(8px) scale(.98); } }
.ax-surface { background: var(--surface); box-shadow: inset 0 1px 0 rgba(255,255,255,.05), 0 0 0 1px rgba(255,255,255,.08), 0 50px 90px -50px rgba(0,0,0,1); }

/* ---- 01 · editor: the model is a collaborator cursor ---- */
.ax-editor { position: relative; width: 100%; height: 360px; border-radius: 14px; overflow: hidden; display: flex; flex-direction: column; }
.ax-editor .ax-tabs { flex: none; display: flex; align-items: flex-end; gap: 2px; height: 40px; padding: 0 10px; background: #0e0d0c; border-bottom: 1px solid var(--line); font-size: 13px; }
.ax-editor .ax-tab { padding: 8px 14px; border-radius: 8px 8px 0 0; color: var(--fg-3); }
.ax-editor .ax-tab.ax-on { background: var(--surface); color: var(--fg); box-shadow: inset 0 1px 0 rgba(255,255,255,.05); }
.ax-editor .ax-code { flex: 1; padding: 16px 0; font: 13px/1.95 var(--f-mono); color: var(--fg-2); counter-reset: ln; position: relative; }
.ax-editor .ax-ln { position: relative; display: block; min-height: 1.95em; padding: 0 20px 0 56px; white-space: pre; transition: background-color .4s, opacity .4s; }
.ax-editor .ax-ln::before { counter-increment: ln; content: counter(ln); position: absolute; left: 0; width: 38px; text-align: right; color: #55514b; }
.ax-editor .ax-ln.ax-del { background: rgba(224,128,110,.12); }
.ax-editor .ax-ln.ax-del .ax-tx { text-decoration: line-through; text-decoration-color: rgba(224,128,110,.7); color: #b98a80; }
.ax-editor .ax-ln.ax-add { background: rgba(95,211,154,.1); }
.ax-editor .ax-ln.ax-add::after { content: '+'; position: absolute; left: 44px; color: var(--good); }
.ax-editor .ax-ln.ax-del::after { content: '−'; position: absolute; left: 44px; color: var(--bad); }
.ax-editor .ax-k { color: #c9a27a; } .ax-editor .ax-f { color: #e6e3de; } .ax-editor .ax-c { color: #6f6b65; }
.ax-editor .ax-status { flex: none; display: flex; align-items: center; gap: 16px; height: 34px; padding: 0 14px; border-top: 1px solid var(--line); background: #0e0d0c; font: 12px var(--f-mono); color: var(--fg-3); }
.ax-editor .ax-status .ax-tests { display: inline-flex; align-items: center; gap: 7px; }
.ax-editor .ax-status .ax-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--bad); }
.ax-editor .ax-status .ax-tests.ax-ok .ax-dot { background: var(--good); }
.ax-editor .ax-status .ax-tests.ax-ok { color: var(--good); }
.ax-editor .ax-status .ax-r { margin-left: auto; }
.ax-cursor { position: absolute; left: 0; top: 0; z-index: 4; pointer-events: none; transition: transform 1.1s cubic-bezier(.5,0,.2,1); }
.ax-cursor svg { width: 16px; height: 18px; display: block; filter: drop-shadow(0 2px 4px rgba(0,0,0,.5)); }
.ax-cursor .ax-who { position: absolute; left: 13px; top: 15px; white-space: nowrap; padding: 3px 8px; border-radius: 4px 9px 9px 9px; background: var(--brand); color: #fff; font: 500 12px var(--f-body); }
.ax-note { position: absolute; z-index: 3; right: 18px; padding: 8px 11px; border-radius: 10px; font-size: 13px; color: var(--fg); background: var(--surface-2); box-shadow: 0 0 0 1px rgba(233,125,73,.35), 0 14px 30px -14px rgba(0,0,0,.9); max-width: 220px; }
.ax-note b { display: block; font: 500 12px var(--f-mono); color: var(--brand-ink); margin-bottom: 2px; }
.ax-toast { position: absolute; z-index: 5; right: 14px; top: 52px; display: inline-flex; align-items: center; gap: 8px; padding: 8px 12px; border-radius: 10px; font-size: 13px; color: var(--fg); background: var(--surface-2); box-shadow: 0 0 0 1px rgba(95,211,154,.35), 0 14px 30px -14px rgba(0,0,0,.9); }
.ax-toast i { font-style: normal; color: var(--good); }
.ax-scene[data-scene="code"] .ax-replay { right: 14px; bottom: 44px; }

/* ---- 02 · phone: the assistant comes to you ---- */
.ax-phone { position: relative; width: 236px; height: 470px; border-radius: 42px; padding: 9px; background: linear-gradient(180deg, #2a2724, #191715); box-shadow: inset 0 0 0 1px rgba(255,255,255,.1), 0 50px 90px -40px rgba(0,0,0,1); }
.ax-phone .ax-screen { position: relative; height: 100%; border-radius: 34px; overflow: hidden; background: radial-gradient(120% 70% at 50% 0%, #2b1a12 0%, #140f0c 55%, #0c0a09 100%); }
.ax-phone .ax-isle { position: absolute; left: 50%; top: 10px; width: 78px; height: 22px; border-radius: 12px; background: #000; transform: translateX(-50%); z-index: 3; }
.ax-phone .ax-clock { position: absolute; left: 0; right: 0; top: 46px; text-align: center; color: #f3efe9; }
.ax-phone .ax-clock small { display: block; font-size: 12px; color: rgba(243,239,233,.7); }
.ax-phone .ax-clock b { display: block; font-size: 44px; font-weight: 300; letter-spacing: -0.03em; line-height: 1.05; }
.ax-phone .ax-stack { position: absolute; left: 9px; right: 9px; top: 140px; display: grid; gap: 7px; }
.ax-notif { padding: 9px 11px 10px; border-radius: 16px; background: rgba(48,44,40,.72); backdrop-filter: blur(12px); box-shadow: inset 0 0 0 1px rgba(255,255,255,.06); color: #ece8e2; font-size: 12px; line-height: 1.35; animation: ax-drop .6s var(--spring) both; }
.ax-notif .ax-h { display: flex; align-items: center; gap: 6px; margin-bottom: 3px; font-size: 12px; color: rgba(236,232,226,.7); }
.ax-notif .ax-h .ax-ic { width: 16px; height: 16px; border-radius: 5px; background: #2a2622 url(../assets/flame2.png) center / 10px no-repeat; box-shadow: inset 0 0 0 1px rgba(255,255,255,.08); }
.ax-notif .ax-h .ax-t { margin-left: auto; }
.ax-notif b { font-weight: 600; }
.ax-notif .ax-acts { display: flex; gap: 6px; margin-top: 8px; }
.ax-notif .ax-acts span { flex: 1; text-align: center; padding: 5px 0; border-radius: 9px; background: rgba(255,255,255,.08); font-size: 12px; }
.ax-notif .ax-acts span.ax-go { background: var(--brand); color: #fff; }
.ax-notif.ax-ok { box-shadow: inset 0 0 0 1px rgba(95,211,154,.3); }
.ax-notif.ax-ok b { color: var(--good); }
@keyframes ax-drop { from { opacity: 0; transform: translateY(-14px) scale(.96); } }
.ax-phone .ax-home { position: absolute; left: 50%; bottom: 8px; width: 90px; height: 4px; border-radius: 2px; background: rgba(255,255,255,.45); transform: translateX(-50%); }
.ax-scene[data-scene="phone"] .ax-replay { left: calc(50% + 138px); bottom: 20px; }

/* ---- 03 · store: an X-ray lens shows what the model sees ---- */
.ax-store { position: relative; width: 100%; height: 400px; border-radius: 14px; overflow: hidden; display: flex; flex-direction: column; }
.ax-store .ax-chrome { flex: none; display: flex; align-items: center; gap: 10px; height: 38px; padding: 0 12px; background: #0e0d0c; border-bottom: 1px solid var(--line); }
.ax-store .ax-chrome .ax-dots { display: flex; gap: 5px; } .ax-store .ax-chrome .ax-dots i { width: 8px; height: 8px; border-radius: 50%; background: #2c2a27; }
.ax-store .ax-chrome .ax-url { flex: 1; max-width: 260px; margin: 0 auto; height: 24px; border-radius: 6px; background: rgba(255,255,255,.05); display: grid; place-items: center; font-size: 12px; color: var(--fg-3); }
.ax-store .ax-page { position: relative; flex: 1; padding: 22px; display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.ax-store .ax-shot { border-radius: 10px; background: #1b1917; box-shadow: inset 0 0 0 1px rgba(255,255,255,.04); }
.ax-store .ax-info { display: grid; align-content: start; gap: 10px; padding-top: 6px; }
.ax-store .ax-info i { display: block; height: 10px; border-radius: 5px; background: rgba(255,255,255,.07); }
.ax-store .ax-info i.ax-t { height: 16px; width: 70%; background: rgba(255,255,255,.12); }
.ax-store .ax-info i.ax-p { width: 30%; background: rgba(233,125,73,.3); }
.ax-store .ax-info i.ax-b { height: 30px; width: 55%; margin-top: 10px; border-radius: 8px; background: rgba(255,255,255,.1); }
.ax-widget { position: absolute; right: 16px; bottom: 16px; width: 318px; border-radius: 16px; overflow: hidden; background: #1c1a18; box-shadow: 0 0 0 1px rgba(255,255,255,.1), 0 30px 60px -20px rgba(0,0,0,.95); font-size: 13px; line-height: 1.45; }
.ax-widget .ax-wh { display: flex; align-items: center; gap: 8px; padding: 10px 12px; border-bottom: 1px solid var(--line); font-size: 13px; color: var(--fg-2); }
.ax-widget .ax-wh .ax-on { width: 7px; height: 7px; border-radius: 50%; background: var(--good); }
.ax-widget .ax-wh .ax-m { margin-left: auto; font: 12px var(--f-mono); color: var(--fg-3); }
.ax-widget .ax-wb { position: relative; padding: 12px; display: grid; gap: 8px; min-height: 176px; align-content: start; }
.ax-bub { padding: 8px 11px; border-radius: 13px; max-width: 92%; }
.ax-bub.ax-cust { touch-action: none; justify-self: end; background: #2c2926; color: var(--fg); border-bottom-right-radius: 4px; position: relative; }
.ax-bub.ax-bot { justify-self: start; background: rgba(191,60,27,.16); color: #ecdcd2; border-bottom-left-radius: 4px; }
.ax-bub .ax-back { color: #fff; font-weight: 500; border-radius: 3px; animation: ax-back 1.6s var(--ease); }
@keyframes ax-back { 0% { background: rgba(95,211,154,.35); box-shadow: 0 0 0 2px rgba(95,211,154,.35); } 100% { background: transparent; box-shadow: none; } }
.ax-pii { display: inline-block; vertical-align: bottom; }
.ax-xray { position: absolute; inset: 0; padding: inherit; pointer-events: none; border-radius: inherit; background: #2a160f; color: #f0c7ad; clip-path: circle(0px at 50% 50%); }
.ax-xray .ax-pii { font: 12px/1.6 var(--f-mono); color: var(--hot); text-align: center; background: rgba(191,60,27,.3); border-radius: 3px; overflow: hidden; white-space: nowrap; }
.ax-lens { position: absolute; z-index: 4; width: 96px; height: 96px; border-radius: 50%; pointer-events: none; transform: translate(-50%, -50%); box-shadow: 0 0 0 1.5px rgba(243,162,114,.85), 0 0 0 6px rgba(243,162,114,.12), 0 12px 30px -8px rgba(0,0,0,.8); opacity: 0; transition: opacity .3s; }
.ax-lens.ax-on { opacity: 1; }
.ax-lens span { position: absolute; left: 50%; top: calc(100% + 8px); transform: translateX(-50%); white-space: nowrap; padding: 3px 8px; border-radius: 999px; font: 500 12px var(--f-body); color: #fff; background: var(--brand); }
.ax-widget .ax-hint { padding: 0 12px 10px; font-size: 12px; color: var(--fg-3); }
.ax-scene[data-scene="store"] .ax-replay { left: 16px; bottom: 16px; }
.ax-scene[data-scene="store"].ax-done .ax-store { cursor: none; }

/* ---- 04 · board: a team of models moving cards ---- */
.ax-board { position: relative; width: 100%; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.ax-col { min-height: 430px; padding: 10px; border-radius: 14px; background: rgba(255,255,255,.025); box-shadow: inset 0 0 0 1px rgba(255,255,255,.05); display: flex; flex-direction: column; gap: 8px; }
.ax-col h4 { margin: 2px 4px 4px; display: flex; justify-content: space-between; font-size: 13px; font-weight: 500; color: var(--fg-3); }
.ax-col h4 b { font: 400 12px var(--f-mono); }
.ax-card { position: relative; padding: 10px 24px 10px 11px; border-radius: 11px; background: var(--surface-2); box-shadow: inset 0 1px 0 rgba(255,255,255,.04), 0 0 0 1px rgba(255,255,255,.07), 0 10px 20px -14px rgba(0,0,0,.9); font-size: 13px; line-height: 1.35; color: var(--fg); will-change: transform; }
.ax-card .ax-who { margin-top: 9px; display: flex; align-items: center; gap: 7px; font: 12px var(--f-mono); color: var(--fg-3); }
.ax-card .ax-who > span:last-child { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.ax-card .ax-av { width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; background: #0e0d0c; box-shadow: inset 0 0 0 1px rgba(255,255,255,.1); }
.ax-card .ax-av img { width: 12px; height: 12px; }
.ax-card .ax-av img.ax-inv { filter: invert(1); }
.ax-card .ax-pg { margin-top: 8px; height: 3px; border-radius: 2px; background: rgba(255,255,255,.07); overflow: hidden; display: none; }
.ax-card .ax-pg i { display: block; height: 100%; width: 0; background: var(--brand-ink); }
.ax-card.ax-doing { box-shadow: inset 0 1px 0 rgba(255,255,255,.04), 0 0 0 1px rgba(233,125,73,.4), 0 10px 24px -12px rgba(191,60,27,.45); }
.ax-card.ax-doing .ax-pg { display: block; }
.ax-card.ax-done { color: var(--fg-2); }
.ax-card.ax-done::after { content: '✓'; position: absolute; right: 10px; top: 9px; font-size: 12px; color: var(--good); }
.ax-card.ax-crit { box-shadow: 0 0 0 1px rgba(233,125,73,.55), 0 14px 30px -12px rgba(191,60,27,.55); color: var(--fg); }
.ax-card.ax-crit .ax-sev { white-space: nowrap;  display: inline-block; margin-top: 7px; padding: 2px 7px; border-radius: 999px; font: 500 12px var(--f-mono); color: #fff; background: var(--brand); }
.ax-scene[data-scene="board"] .ax-replay { right: 10px; bottom: -40px; }


@media (max-width: 600px) {
  .ax-sky { height: 350px; }
  .ax-editor { height: 330px; }
  .ax-editor .ax-code { font-size: 12px; }
  .ax-editor .ax-ln { padding-left: 46px; padding-right: 10px; }
  .ax-editor .ax-ln::before { width: 30px; }
  .ax-editor .ax-ln.ax-add::after, .ax-editor .ax-ln.ax-del::after { left: 35px; }
  .ax-store { height: 430px; }
  .ax-store .ax-page { grid-template-columns: 1fr; padding: 14px; }
  .ax-store .ax-info { display: none; }
  .ax-store .ax-shot { height: 120px; }
  .ax-widget { left: 12px; right: 12px; width: auto; bottom: 12px; }
  .ax-board { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
  .ax-col { min-height: 420px; padding: 6px; gap: 6px; }
  .ax-card { padding: 8px; font-size: 12px; }
  .ax-card .ax-who span { display: none; }
  .ax-scene[data-scene="phone"] .ax-replay { left: auto; right: 0; }
  .ax-scene[data-scene="store"] .ax-replay { left: auto; right: 10px; bottom: auto; top: 46px; }
  .ax-scene[data-scene="code"] .ax-toast { top: 48px; bottom: auto; }
  .ax-scene[data-scene="code"] .ax-replay { bottom: auto; top: 6px; right: 10px; }
}
@media (prefers-reduced-motion: reduce) {
  .ax-flame .ax-inner, .ax-ember, .ax-spin { animation: none !important; }
  .ax-flame .ax-tongues, .ax-flame .ax-inner { filter: none; }
}
